create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text not null default '',role text not null default 'customer' check(role in('customer','admin')),created_at timestamptz not null default now());
create table if not exists public.packages(id uuid primary key default gen_random_uuid(),name text not null,price_kes integer not null check(price_kes>0),duration_seconds integer not null check(duration_seconds>0),duration_label text not null,speed_label text not null default 'Fast access',description text not null default '',is_active boolean not null default true,is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.purchases(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete restrict,customer_email text not null,package_id uuid references public.packages(id) on delete set null,package_name text not null,amount_kes integer not null check(amount_kes>0),duration_seconds integer not null check(duration_seconds>0),status text not null default 'pending' check(status in('pending','paid','failed')),activation_status text not null default 'pending' check(activation_status in('pending','provisioning','active','failed')),activation_error text,paystack_reference text unique,paystack_transaction_id text,hotspot_username text,hotspot_password text,paid_at timestamptz,activated_at timestamptz,created_at timestamptz not null default now());
create index if not exists purchases_user_created_idx on public.purchases(user_id,created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'phone','')) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
revoke all on function public.is_admin() from public;grant execute on function public.is_admin() to authenticated;
alter table public.profiles enable row level security;alter table public.packages enable row level security;alter table public.purchases enable row level security;
drop policy if exists "profiles self or admin read" on public.profiles;create policy "profiles self or admin read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
drop policy if exists "profiles own update" on public.profiles;create policy "profiles own update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());revoke update on public.profiles from authenticated;grant update(full_name,phone) on public.profiles to authenticated;grant select on public.profiles to authenticated;
drop policy if exists "packages public active read" on public.packages;create policy "packages public active read" on public.packages for select to anon,authenticated using(is_active=true or public.is_admin());
drop policy if exists "admins manage packages" on public.packages;create policy "admins manage packages" on public.packages for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "purchases owner or admin read" on public.purchases;create policy "purchases owner or admin read" on public.purchases for select to authenticated using(user_id=auth.uid() or public.is_admin());
grant select on public.packages to anon,authenticated;grant select on public.purchases to authenticated;
insert into public.packages(name,price_kes,duration_seconds,duration_label,speed_label,description,is_active,is_featured) select '1 Hour',20,3600,'1 hour','Fast access','Quick browsing and messaging.',true,false where not exists(select 1 from public.packages);
insert into public.packages(name,price_kes,duration_seconds,duration_label,speed_label,description,is_active,is_featured) select '6 Hours',60,21600,'6 hours','Fast access','Work, study and everyday browsing.',true,true where (select count(*) from public.packages)=1;
insert into public.packages(name,price_kes,duration_seconds,duration_label,speed_label,description,is_active,is_featured) select '24 Hours',100,86400,'24 hours','Fast access','Full-day access for a busy day.',true,false where (select count(*) from public.packages)=2;
